export function getLegoPart(id) {
  return LEGO_TECHNIC_PARTS.find(p => p.id === id);
}

export function getLegoPartsBySubcat(subcat) {
  return LEGO_TECHNIC_PARTS.filter(p => p.subcat === subcat);
}

export function searchLegoParts(query) {
  const q = query.trim().toLowerCase();
  if (!q) return LEGO_TECHNIC_PARTS;
  return LEGO_TECHNIC_PARTS.filter(p =>
    p.name.toLowerCase().includes(q) ||
    p.partNum.toLowerCase().includes(q) ||
    p.color.toLowerCase().includes(q)
  );
}
